  },
  // ... 3 more tabs
];
```

Entry points follow consistent pattern: each tab has both `tab.ts` (main class) and `index.ts` (re-export).

---

### **2. TAB ENTRY POINTS & INTERNAL STRUCTURE**

| Tab | Tab Class | Size | Internal Structure | Key Controllers |
|-----|-----------|------|-------------------|-----------------|
| **ChatBot** | ChatbotTab | 96 lines | chatApp → agent + features + utils | ChatApp (536L), ModelSelector, StreamingController |
| **GameCenter** | GameCenterTab | 393 lines | queries → direct rendering | None (monolithic) |
| **TimeMachine** | TimeMachineTab | 482 lines | 3 controllers + shared UI | PlayerModeController (429L), TeamModeController (239L), BbrViewController (404L) |
| **SqlSandbox** | SqlSandboxTab | 444 lines | 2 sub-components | SchemaBrowser, AutocompleteController |

**Total codebase: ~10,274 lines (excluding tests)**

---

### **3. MAJOR DUPLICATION & INCONSISTENCY PATTERNS**

#### **A. Focus Management Pattern Duplication**

**Three different approaches:**

1. **GameCenter & SqlSandbox use `FocusManager` utility (src/shared/ui/)**
   - GameCenter: `src/tabs/gameCenter/tab.ts:85, 133, 159-166`
   ```typescript
   private readonly focusManager: FocusManager;

   constructor(renderer: CliRenderer) {
     this.focusManager = new FocusManager([this.leftPanel, this.middlePanel, this.rightPanel]);
   }

   cycleFocus() {
     this.focusManager.next();
     this.applyFocus();
   }
   ```

   - SqlSandbox: `src/tabs/sqlSandbox/tab.ts:51, 162, 218-231`
   ```typescript
   private readonly focusManager: FocusManager;

   cycleFocus() {
     this.focusManager.next();
     if (this.focusManager.currentIndex === 0) {
       this.schemaFocusTarget = 'filter';  // Extra state management
     }
     this.focus();
   }
   ```

   **Issue:** SqlSandbox duplicates cycling logic and adds ad-hoc `schemaFocusTarget` state, while GameCenter reuses the same pattern verbatim.

2. **TimeMachine implements its own focus with manual index cycling**
   - `src/tabs/timeMachine/tab.ts:104-105, 316-332`
   ```typescript
   focusIndex = 0;
   teamFocusIndex = 0;

   cycleFocus(): void {
     if (this.mode === 'player') {
       this.focusIndex = (this.focusIndex + 1) % PLAYER_FOCUS_PANELS;
     } else {
       this.teamFocusIndex = (this.teamFocusIndex + 1) % TEAM_FOCUS_PANELS;
     }
     this.focus();
   }
   ```

   **Issue:** Manually implements what `FocusManager` already does, with extra logic for dual-mode switching.

3. **ChatBot doesn't have multi-panel focus; uses direct input/scroll toggling**
   - `src/tabs/chatbot/chatApp.ts:270-287`
   ```typescript
   if (event.name === 'tab') {
     if (event.shift) {
       if (this.chatScroll.focused) this.promptInput.focus();
       else this.chatScroll.focus();
     } else {
       if (this.promptInput.focused) this.chatScroll.focus();
       else this.promptInput.focus();
     }
   }
   ```

**Consolidation Opportunity:** Abstract a unified `FocusManager` that handles both dual-input and multi-panel scenarios.

---

#### **B. Input Blur/Escape Handling Duplication**

All tabs reimplement similar logic:

- **GameCenter**: `src/tabs/gameCenter/tab.ts:204-206` (no-op)
- **ChatBot**: `src/tabs/chatbot/tab.ts:83-90` (blur or cancel if processing)
- **SqlSandbox**: `src/tabs/sqlSandbox/tab.ts:286-299` (complex state management)
  ```typescript
  blurInput() {
    const idx = this.focusManager.currentIndex;
    if (idx === 1) {
      this.sqlInput.blur();
      this.focusManager.setIndex(0);
      this.schemaFocusTarget = 'tree';
      this.focus();
    } else if (idx === 0 && this.schemaFilterInput.focused) {
      this.schemaFilterInput.blur();
      this.focusManager.setIndex(1);
      this.schemaFocusTarget = 'filter';
      this.focus();
    }
  }
  ```
- **TimeMachine**: `src/tabs/timeMachine/tab.ts:393-403` (mode-aware blur)
  ```typescript
  blurInput(): void {
    if (this.mode === 'player') {
      this.searchInput.blur();
      this.focusIndex = 1;
    } else {
      this.teamAInput.blur();
      this.teamBInput.blur();
      this.teamFocusIndex = 2;
    }
    this.focus();
  }
  ```

**Issue:** Each has custom logic; no shared pattern. All reinvent setting focus state after blur.

---

#### **C. Status Line Building Duplication**

All four tabs implement `getStatusLine()` with similar structure:

- **GameCenter**: `src/tabs/gameCenter/tab.ts:168-184` (27 lines)
  ```typescript
  getStatusLine(): string {
    const gameCount = this.games.length;
    const gamePos = gameCount > 0 ? `${this.selectedGameIdx + 1}/${gameCount}` : '0/0';
    const panelLabels = ['Games', 'Box score', 'Shot chart'];
    const panel = panelLabels[this.focusManager.currentIndex] ?? 'Games';

    let playerLabel = 'All Players';
    if (this.selectedPlayerIdx >= 0 && this.boxScores[this.selectedPlayerIdx]) {
      playerLabel = this.boxScores[this.selectedPlayerIdx].full_name;
    }

    const idx = this.focusManager.currentIndex;
    const moveHint = idx === 0 ? '↑↓ move game' : idx === 1 ? '↑↓ move player' : 'read-only';
    return `Games ${gamePos} | ${panel} | Player: ${playerLabel} | ${moveHint}`;
  }
  ```

- **SqlSandbox**: `src/tabs/sqlSandbox/tab.ts:233-250` (18 lines)
  ```typescript
  getStatusLine(): string {
    const parts: string[] = [`Focus: ${PANEL_NAMES[this.focusManager.currentIndex]}`];
    const node = this.schemaBrowser.getSelectedNode();
    if (node?.type === 'table') {
      parts.push(`Table: ${node.name}`);
    } else if (node?.type === 'column' && node.tableName) {
      parts.push(`Column: ${node.tableName}.${node.name}`);
    }

    if (this.errorMessage) {
      parts.push(`Error: ${this.errorMessage}`);
    } else if (this.executionTimeMs > 0 || this.rowsReturned > 0) {
      parts.push(`Rows: ${this.rowsReturned}`);
    }

    return parts.join(' | ');
  }
  ```

- **ChatBot**: `src/tabs/chatbot/tab.ts:73-76` (4 lines, delegates)
- **TimeMachine**: `src/tabs/timeMachine/tab.ts:334-384` (50 lines, mode-branching)

**Pattern:** All use string joining with separator `|` or `·`. TimeMachine uses separate helper functions (`buildPlayerStatusLine`, `buildTeamStatusLine`).

**Consolidation Opportunity:** Create a `StatusLineBuilder` utility with composable parts.

---

#### **D. Panel Creation & Initialization Duplication**

All tabs use the same shared `createPanel()` and `createScrollPanel()` helpers, but each tabs reinvents the same wrapping code:

- **GameCenter**: `src/tabs/gameCenter/tab.ts:97-133`
- **SqlSandbox**: `src/tabs/sqlSandbox/tab.ts:82-160`
- **TimeMachine**: `src/tabs/timeMachine/tab.ts:130-220`

Pattern (all three):
```typescript
const scrollPanel = createScrollPanel(renderer, { id: 'xxx', title: '...', width: '...' });
this.xxxPanel = scrollPanel.panel;
this.xxxScroll = scrollPanel.scroll;
this.xxxText = scrollPanel.text;

this.container.add(this.xxxPanel);

// Later, input event listeners:
this.xxxInput.on('input', () => { /* update state */ });
this.xxxInput.on('enter', () => { /* trigger action */ });
```

**Issue:** No abstraction for "panel + input → render" lifecycle. Each tab hardcodes listener attachment.

---

#### **E. Error Handling Pattern Duplication**

All tabs wrap `init()` in try/catch but handle errors inconsistently:

- **GameCenter**: `src/tabs/gameCenter/tab.ts:137-151`
  ```typescript
  async init() {
    try {
      this.games = await loadRecentGames();
      if (this.games.length > 0) {
        this.selectedGameIdx = 0;
        this.renderGameList();
        await this.loadGameDetails();
      } else {
        this.gameListText.content = ansiToStyledText('No games found in database.');
      }
    } catch (e: unknown) {
      this.gameListText.content = ansiToStyledText(`Error loading games:\n${getErrorMessage(e)}`);
      this.container.requestRender();
    }
  }
  ```

- **SqlSandbox**: `src/tabs/sqlSandbox/tab.ts:182-196`
  ```typescript
  async init() {
    try {
      const catalog = await loadSchemaCatalog();
      this.tables = catalog.tables;
      this.tableColumns = catalog.tableColumns;
      this.autocomplete.loadSchema(this.tables, this.tableColumns);
      this.schemaBrowser.loadData(this.tables, this.tableColumns);
      await this.schemaBrowser.rebuild();
      this.schemaBrowser.render();
      this.container.requestRender();
    } catch (e: unknown) {
      this.schemaText.content = ansiToStyledText(`Error loading schema:\n${getErrorMessage(e)}`);
      this.container.requestRender();
    }
  }
  ```

- **ChatBot**: `src/tabs/chatbot/tab.ts:31-54` (also wraps app construction)
  ```typescript
  try {
    await initChatbotDb();
    const systemPrompt = await buildSystemPrompt();
    this.chatApp = new ChatApp(this.renderer, systemPrompt, { containerMode: true });
    this.container.add(this.chatApp.container);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    this.errorText = new TextRenderable(this.renderer, { content: ansiToStyledText(...) });
    this.container.add(this.errorText);
  }
  ```

**Issue:** Each tab stores error state differently (some in TextRenderable, some in a field), making it hard to add error recovery across the app.

---

#### **F. Table Formatting Duplication**

Three tabs use `formatTable()` from shared utils with similar column-mapping logic:

- **GameCenter**: `src/tabs/gameCenter/tab.ts:28-38, 303-306`
  ```typescript
  const BOX_SCORE_HEADERS = ['Player', 'Team', 'MIN', 'PTS', 'AST', 'REB', 'STL', 'BLK'];
  const BOX_SCORE_KEYS = ['full_name', 'team_abbrev', 'min', 'points', 'assists', 'reb', 'steals', 'blocks'];

  const tableLines = formatTable(BOX_SCORE_HEADERS, [allRow, ...mappedRows], {
    colKeys: BOX_SCORE_KEYS,
  });
  ```

- **SqlSandbox**: `src/tabs/sqlSandbox/tab.ts:421-433`
  ```typescript
  const firstRow = this.queryResult[0];
  const headers = Object.keys(firstRow);
  const tableLines = formatTable(headers, this.queryResult, { maxRows: 100 });
  ```

- **TimeMachine (playerMode)**: `src/tabs/timeMachine/playerMode.ts:305-315`
  ```typescript
  const headers = [...]; // computed
  const tableLines = formatTable(headers, formattedRows, { colKeys: keys });
  ```

**Issue:** No typed table schema abstraction. Each reinvents column ordering and mapping.

---

#### **G. Key Press Handling Duplication**

**Pattern 1: Focus-index-based dispatch** (GameCenter, SqlSandbox)
- `src/tabs/gameCenter/tab.ts:208-220`
- `src/tabs/sqlSandbox/tab.ts:301-322`

Both:
```typescript
handleKeyPress(event: AppKeyEvent): boolean {
  const idx = this.focusManager.currentIndex;
  if (idx === 0) return this.handlePanelAKeys(event);
  if (idx === 1) return this.handlePanelBKeys(event);
  return false;
}
```

**Pattern 2: Mode/state-aware dispatch** (TimeMachine)
- `src/tabs/timeMachine/tab.ts:405-425`
```typescript
handleKeyPress(event: AppKeyEvent): boolean {
  const key = (event.sequence || event.name || '').toLowerCase();
  if (this.tryBbrKeys(event, key)) return true;
  if (!this.isInputFocused() && (event.name === 'c' || event.sequence === 'c')) {
    this.toggleMode();
    return true;
  }

  if (event.name === 'tab') {
    if (this.isInputFocused()) {
      if (event.shift) this.cycleFocusBackward();
      else this.cycleFocus();
      return true;
    }
  }

  if (this.mode === 'player') return this.playerMode.handleKeyPress(event);
  return this.teamMode.handleKeyPress(event);
}
```

**Pattern 3: Nested overlay dispatch** (ChatBot)
- `src/tabs/chatbot/chatApp.ts:254-288`
```typescript
handleKeyPress(event: AppKeyEvent): boolean {
  if (this.modelSelector.overlay.visible) {
    return this.modelSelector.handleKeyPress(event);
  }

  if (event.name === '@' || (event.ctrl && event.name === 'p')) {
    this.modelSelector.show();
    return true;
  }

  if (event.name === 'escape' && this.isProcessing) {
    this.processingCancelled = true;
    this.abortController?.abort();
    return true;
  }

  if (event.name === 'tab') {
    // ... custom tab handling
  }
  return false;
}
```

**Issue:** Three incompatible patterns with no abstraction. Hard to add new tabs without choosing a pattern and reimplementing the dispatcher.

---

#### **H. Panel Visibility Toggle Duplication**

**Only TimeMachine has this (src/tabs/timeMachine/teamMode.ts:17-28):**
```typescript
showPanels(): void {
  this.host.searchPanel.visible = false;
  this.host.dossierPanel.visible = false;
  this.host.teamSearchPanel.visible = true;
  this.host.teamFocusIndex = 0;
}

hidePanels(): void {
  this.host.searchPanel.visible = true;
  this.host.dossierPanel.visible = true;
  this.host.teamSearchPanel.visible = false;
}
```

This is hardcoded to TimeMachine's specific panels. If another tab needs multi-mode UI swapping, this pattern would need to be reimplemented.

**Issue:** No abstraction for panel state management. Each panel's visibility is manually set.

---

#### **I. Rendering Pattern Duplication**

All tabs have private `render*()` methods that convert state to ANSI text:

**GameCenter:**
- `renderGameList()` @ line 281
- `renderBoxScore()` @ line 287
- `renderShotChart()` @ line 310

**SqlSandbox:**
- `renderResults()` @ line 421

**TimeMachine (distributed across controllers):**
- `renderDossier()` in PlayerModeController @ line 217
- `renderStats()` in PlayerModeController @ line 257
- `renderTeamComparison()` in TeamModeController @ line 109
- `renderTeamInstructions()` in TeamModeController @ line 204
- `renderSiteCatalog()` in BbrViewController

**ChatBot:**
- `renderDisplay()` @ line 495
- `renderStreaming()` @ line 489

**Issue:** No shared rendering pipeline. Each tab designs its own render-and-notify pattern. No way to batch renders or handle render failures uniformly.

---

### **4. INCONSISTENT FILE ORGANIZATION**

| Tab | Has Queries | Has Utils Subdir | Has Controllers | Has Config Files |
|-----|-----------|------------------|-----------------|------------------|
| ChatBot | No (agent/) | Yes (utils/) | Yes (agent/, features/) | Yes (config, systemPrompt, openrouter) |
| GameCenter | Yes (queries.ts) | No | No | No |
| TimeMachine | Yes (queries.ts) | Yes (utils/bbr/, utils/*.ts) | Yes (3 separate) | No |
| SqlSandbox | Yes (queries.ts) | No | Partial (schemaBrowser, autocomplete as classes) | No |

**Observations:**
- ChatBot is the deepest (agent/ with 11 files including graph, orchestrator, tools)
- TimeMachine is widest (utils/bbr with 5 files for web scraping)
- GameCenter is flattest (just queries.ts)
- **No consistent naming convention** for "modes" (PlayerModeController vs BbrViewController vs ModelSelector)

---

### **5. TYPE DEFINITIONS & INTERFACES**

**Each tab defines its own types locally:**
- ChatBot: Scattered in agent/, features/
- GameCenter: Inline in queries.ts
- TimeMachine: `src/tabs/timeMachine/types.ts` (TimeMachineHost interface — only one with explicit types file)
- SqlSandbox: Inline in schemaBrowser.ts, autocomplete.ts

**Issue:** No shared tab-specific types. TimeMachine's `TimeMachineHost` interface is a workaround for multi-controller coordination, but other tabs don't follow this pattern.

---

### **6. CONTROLLER/FEATURE PATTERNS**

**Three different abstractions:**

1. **TimeMachine:** Dedicated controller classes that take the parent tab as `host`
   - `PlayerModeController(host: TimeMachineHost)`
   - `TeamModeController(host: TimeMachineHost)`
   - `BbrViewController(host: TimeMachineHost)`

   Allows controllers to reach back into parent state. **Problem:** Tight coupling; parent is mutable repository.

2. **ChatBot:** Monolithic `ChatApp` that owns all sub-features
   - `ModelSelector` is nested inside; gets callbacks to refresh parent state
   - Agent/graph is stateless orchestrator

   **Problem:** ModelSelector has callback coupling; agent graph is immutable but hard to extend.

3. **SqlSandbox:** Helper classes (`SchemaBrowser`, `AutocompleteController`) that own their state
   - Parent `SqlSandboxTab` wires them together
   - They communicate via event handlers (input listeners)

   **Problem:** No shared state visibility; harder to implement cross-feature behaviors (e.g., clear autocomplete when schema changes).

---

### **7. CRITICAL FINDINGS: HARD-TO-EDIT AREAS**

**Highest Risk of Breakage When Refactoring:**

1. **Focus Management** — Three incompatible patterns would require breaking changes to unify.

2. **KeyPress Dispatching** — Each tab's `handleKeyPress()` is tightly bound to its focus/mode state. Hard to add middleware, shortcuts, or global commands.

3. **TimeMachine's Dual-Mode Panel Toggling** — `showPanels()/hidePanels()` in `teamMode.ts` hardcodes which panels are visible. If you want to add a third mode, you need to refactor this everywhere.

4. **Error State** — No central error sink. Each tab stores errors in different fields/renderables.

5. **Render Cycles** — No batching or queueing. Calling `renderXxx()` immediately calls `container.requestRender()`. If multiple features trigger renders, you get redundant redraws.

---

### **8. REFACTOR RECOMMENDATIONS (Modular, Extensible, No Behavior Change)**

**Priority 1: Extract Shared Abstractions**

1. **`FocusManager` upgrade** — Support dual-input mode (2-way toggle) and multi-panel (N-way cycle):
   ```typescript
   abstract class FocusController {
     abstract focus(): void;
     abstract cycleFocus(): void;
     abstract cycleFocusBackward(): void;
   }

   class DualInputFocusController implements FocusController { }
   class MultiPanelFocusController implements FocusController { }
   ```

2. **`TabController` base class** — Enforce uniform interface:
   ```typescript
   abstract class TabController {
     abstract getStatusLine(): string;
     abstract blurInput(): void;
     protected renderAndNotify(content: string): void {
       this.text.content = ansiToStyledText(content);
       this.container.requestRender();
     }
   }
   ```

3. **`PanelGroup` abstraction** — Manage visibility, focus, and rendering:
   ```typescript
   class PanelGroup {
     addPanel(id: string, panel: BoxRenderable, label: string): void;
     showMode(modeId: string): void;  // Shows only panels in mode
     cycleFocus(): void;
     getStatusLabel(): string;
   }
   ```

**Priority 2: Consolidate Key Handling**

1. Create a `KeyDispatcher` that can be subclassed:
   ```typescript
   class KeyDispatcher {
     protected dispatchToFocus(event: AppKeyEvent): boolean;
     protected dispatchToMode(event: AppKeyEvent): boolean;
     protected dispatchOverlay(event: AppKeyEvent): boolean;

     abstract handleKeyPress(event: AppKeyEvent): boolean;
   }
   ```

2. Move global shortcuts (Esc, Tab, ?) to shell level, let tabs handle only custom keys.

**Priority 3: Render Pipeline**

1. Introduce a `RenderBatch` to queue renders and flush once:
   ```typescript
   class RenderBatch {
     queueRender(component: string, content: string): void;
     flush(): void;
   }
   ```

**Priority 4: Type Safety**

1. Create `TabState<T>` generic for each tab's state:
   ```typescript
   interface TabState {
     focusIndex: number;
     errorMessage: string | null;
     isLoading: boolean;
   }
   ```

2. Require all modes/controllers to declare their dependencies on `TabState` fields.

---

### **SUMMARY TABLE: Duplication by Category**

| Duplication Category | Affected Tabs | Severity | Refactor Effort |
|----------------------|---------------|----------|-----------------|
| **Focus Management** | All 4 | **High** | Medium (need abstraction + tests) |
| **Input Blur Logic** | All 4 | Medium | Low (centralize into base) |
| **Status Line Building** | All 4 | Low-Medium | Low (utility function) |
| **Error Handling** | All 4 | **High** | Medium (unified error sink) |
| **Panel Creation** | GameCenter, SqlSandbox, TimeMachine | Low | Low (template helpers exist) |
| **Table Rendering** | GameCenter, SqlSandbox, TimeMachine | Medium | Medium (typed schema abstraction) |
| **Key Press Dispatch** | All 4 | **High** | High (three patterns; need design) |
| **Panel Visibility** | TimeMachine (only) | Medium | Low (move to PanelGroup) |
| **Rendering Methods** | All 4 | Medium | Low (consolidate into trait) |
| **File Organization** | All 4 | Low | Very Low (docs + conventions) |

---

**Total Estimated Refactor Effort (no behavior change):** 4–6 weeks (phased: foundations week 1–2, migration weeks 3–4, tests/docs weeks 5–6).

