  readonly container: BoxRenderable;

  focus(): void;

  init(): Promise<void>;

  cycleFocus(): void;

  cycleFocusBackward?(): void;

  getStatusLine?(): string;

  isInputFocused(): boolean;

  blurInput(): void;

  handleKeyPress(event: AppKeyEvent): boolean;
}

