324	  private handleSchemaPanelKeys(event: AppKeyEvent): boolean {
325	    if (event.name === 'up') return this.schemaBrowser.moveUp();
326	    if (event.name === 'down') return this.schemaBrowser.moveDown();
327	    if (event.name === 'return' || event.name === 'enter') {
