329	      return true;
330	    }
331	    if (event.name === 'tab') {
332	      if (event.shift) this.cycleFocusBackward();
333	      else this.cycleFocus();
334	      return true;
335	    }
336	    return false;
337	  }
338	
339	  private handleInputPanelKeys(event: AppKeyEvent): boolean {
340	    if (event.name === 'tab') {
341	      if (this.autocomplete.hasSuggestions && !event.shift) {
342	        this.acceptAutocomplete();
343	        return true;
344	      }
345	      if (event.shift) this.cycleFocusBackward();
346	      else this.cycleFocus();
347	      return true;
348	    }
349	
350	    if (this.autocomplete.hasSuggestions) {
351	      if (event.name === 'up') {
352	        this.autocomplete.moveUp();
353	        this.autocomplete.update(this.currentQuery, () => this.container.requestRender());
354	        return true;
355	      }
356	      if (event.name === 'down') {
357	        this.autocomplete.moveDown();
358	        this.autocomplete.update(this.currentQuery, () => this.container.requestRender());
359	        return true;
360	      }
361	    }
362	
363	    return false;
364	  }
365	
366	  private async toggleOrInsertSchemaNode() {
367	    const node = this.schemaBrowser.getSelectedNode();
368	    if (!node) return;
369	
370	    if (node.type === 'table') {
371	      this.schemaBrowser.toggleTable(node.name);
372	      await this.schemaBrowser.rebuild();
373	      this.schemaBrowser.render();
374	      this.container.requestRender();
375	    } else if (node.type === 'column') {
376	      const curVal = this.sqlInput.value;
377	      this.sqlInput.value = `${curVal} ${node.name}`;
378	      this.currentQuery = this.sqlInput.value;
379	      this.autocomplete.update(this.currentQuery, () => this.container.requestRender());
380	
381	      this.focusManager.setIndex(1);
382	      this.focus();
383	    }
384	  }
385	
386	  private acceptAutocomplete() {
387	    this.sqlInput.value = this.autocomplete.accept(this.sqlInput.value);
388	    this.currentQuery = this.sqlInput.value;
389	    this.autocomplete.reset();
390	    this.autocomplete.update(this.currentQuery, () => this.container.requestRender());
391	  }
392	
393	  private async runQuery() {
394	    const sql = this.currentQuery.trim();
395	    if (!sql) return;
396	
397	    this.resultsText.content = ansiToStyledText('Executing query against 1.5GB database...');
398	    this.errorMessage = '';
399	    this.container.requestRender();
400	
401	    const start = performance.now();
402	    try {
403	      this.queryResult = await runSandboxQuery(sql);
404	      this.executionTimeMs = performance.now() - start;
405	      this.rowsReturned = this.queryResult.length;
406	
407	      this.renderResults();
408	    } catch (e: unknown) {
409	      this.errorMessage = getErrorMessage(e);
410	      this.queryResult = [];
411	      this.rowsReturned = 0;
412	      this.executionTimeMs = performance.now() - start;
413	
414	      this.resultsText.content = ansiToStyledText(
415	        `${ansiRed('SQL Error:')}\n${this.errorMessage}\n\nExecution Time: ${this.executionTimeMs.toFixed(1)}ms`,
416	      );
417	      this.container.requestRender();
418	    }
419	  }
420	
421	  private renderResults() {
422	    if (this.queryResult.length === 0) {
423	      this.resultsText.content = ansiToStyledText(
424	        `Statement executed successfully.\nReturned 0 rows.\n\nExecution Time: ${this.executionTimeMs.toFixed(1)}ms`,
425	      );
426	      this.container.requestRender();
427	      return;
428	    }
429	
430	    const firstRow = this.queryResult[0];
431	    const headers = Object.keys(firstRow);
432	
433	    const tableLines = formatTable(headers, this.queryResult, { maxRows: 100 });
434	
435	    const summaryHeader = `${ansiGreen('Query Succeeded!')} Returned ${ansiBold(String(this.rowsReturned))} rows in ${ansiBold(`${this.executionTimeMs.toFixed(1)}ms`)} (showing max 100 rows)\n\n`;
436	
437	    this.resultsText.content = ansiToStyledText(summaryHeader + tableLines.join('\n'));
438	
439	    this.resultsScroll.scrollTop = 0;
440	    this.resultsScroll.scrollLeft = 0;
441	
442	    this.container.requestRender();
443	  }
444	}
445

