347	  /**
348	   * Maps shot x/y to court grid cells (same heuristics as drawHalfCourt).
349	   */
350	  private shotGridCoords(shot: { x: number; y: number }): { gridR: number; gridC: number } {
351	    let xHalf = shot.x;
352	    if (xHalf > 50) {
353	      xHalf = 100 - xHalf;
354	    }
355	    const rows = 18;
356	    const cols = 40;
357	    return {
358	      gridR: Math.floor((xHalf / 50) * (rows - 1)),
359	      gridC: Math.floor((shot.y / 100) * (cols - 1)),
360	    };
361	  }
362	
363	  private classifyShotZone(shot: { x: number; y: number }): 'paint' | 'corner3' | 'three' | 'mid' {
364	    const { gridR, gridC } = this.shotGridCoords(shot);
365	
366	    if (gridR >= 1 && gridR <= 7 && gridC > 13 && gridC < 26) {
367	      return 'paint';
368	    }
369	    if (gridR >= 1 && gridR <= 5 && (gridC <= 2 || gridC >= 37)) {
370	      return 'corner3';
371	    }
372	
373	    let xHalf = shot.x;
374	    if (xHalf > 50) {
375	      xHalf = 100 - xHalf;
376	    }
377	    const dy = (gridR - 2) * (47 / 17);
378	    const dx = (gridC - 20) * (50 / 39);
379	    const dist = Math.sqrt(dx * dx + dy * dy);
380	    if (gridR >= 5 && dist >= 22) {
381	      return 'three';
382	    }
383	    return 'mid';
